pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;

    function setUp() public { lg = new Log(); c = new X_WALLET(address(lg)); }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (, string memory data, , ) = lg.History(0);
        assertTrue(keccak256(bytes(data)) == keccak256(bytes("Put")));
    }
}
